    h, w = len(grid), len(grid[0])
    # Identify grid boundary rows/columns as the regularly repeated separator
    # stripes. Colored corner marks replace separator color at some crossings.
    def stripe_rows():
        return [r for r in range(h) if sum(v in (8, 9) for v in grid[r]) >= w - 2]
    def stripe_cols():
        return [c for c in range(w) if sum(grid[r][c] in (8, 9) for r in range(h)) >= h - 2]
    rs, cs = stripe_rows(), stripe_cols()
    # Boundaries are spaced uniformly; include stripes partly overwritten by marks.
    def regular(vals, limit):
        ds = [b-a for a,b in zip(vals, vals[1:]) if b>a]
        step = min(ds)
        start = vals[0]
        return list(range(start, limit, step))
    rs, cs = regular(rs, h), regular(cs, w)
    bg = next(v for row in grid for v in row if v not in (8, 9, 7, 2))
    out = [[bg for _ in range(len(cs)-1)] for _ in range(len(rs)-1)]
